const TABS = [['otif', 'OTIF & Quality'], ['att', 'Attendance'], ['dmg', 'Damage'], ['ot', 'Overtime'], ['tp', 'Throughput'], ['prod', 'Productivity'], ['trk', 'Trucks'], ['op', 'Operator Moves'], ['osha', 'OSHA Recordables']];

// ---------- Trucks (Truck Appointments log, filled from the dock schedule exports on Weekly Entry) ----------
/** Trucks for the dashboard's building(s) and year, with arrival status, variance and time on site worked out. */
export function truckData(B, year) {
  const cfg = truckCfg();
  const list = store.rows('trucks').filter(r => B.bldgs.includes(String(r.facility)) && String(r.date).startsWith(String(year)))
    .map(r => ({ ...r, ...truckTimes(r, cfg) })).sort((a, z) => (z.date + (z.arrival || z.appointment || '')).localeCompare(a.date + (a.arrival || a.appointment || '')));
  const stats = rows => {
    const rated = rows.filter(t => t.status), n = s => rated.filter(t => t.status === s).length;
    const avg = xs => (xs.length ? xs.reduce((a, x) => a + x, 0) / xs.length : '');
    const outs = rows.filter(t => norm(t.direction) === 'OUT' && t.held != null);
    return { n: rows.length, inN: rows.filter(t => norm(t.direction) === 'IN').length, outN: rows.filter(t => norm(t.direction) === 'OUT').length, rated: rated.length,
      onTime: n('On time'), early: n('Early'), late: n('Late'), pct: rated.length ? n('On time') / rated.length : '',
      avgLate: avg(rated.filter(t => t.status === 'Late').map(t => t.diff)), avgVar: avg(rated.map(t => t.diff)),
      siteIn: avg(rows.filter(t => norm(t.direction) === 'IN' && t.onSite != null).map(t => t.onSite)), siteOut: avg(rows.filter(t => norm(t.direction) === 'OUT' && t.onSite != null).map(t => t.onSite)),
      heldOver: outs.filter(t => t.heldOver === 'Y').length, outRated: outs.length };
  };
  const weeks = [...new Set(list.map(t => weekEndingOf(t.date)))].sort().reverse().map(w => ({ week: w, ...stats(list.filter(t => weekEndingOf(t.date) === w)) }));
  const custs = [...new Set(list.map(t => t.customer || '—'))].map(c => ({ c, ...stats(list.filter(t => (t.customer || '—') === c)) })).sort((a, z) => z.n - a.n);
  return { list, ytd: stats(list), weeks, custs, cfg };
}
