    <div style="margin-top:20px"><div class="xl-trio-title">Latest trucks</div><div class="xl-otif-wrap xl-scroll"><table class="xl-otif"><thead><tr><th>Date</th><th>In / Out</th><th>Customer</th><th>Load #</th><th>Appt</th><th>Time In</th><th>Time Out</th><th>Variance</th><th>Arrival</th><th>On Site</th><th>Carrier</th></tr></thead><tbody>\${recent || '<tr><td colspan="11">No trucks recorded yet.</td></tr>'}</tbody></table></div></div>
